import pandas as pd
import numpy as np

# Load data
no2_df = pd.read_csv('chunks_csv/outlierr/2023_no2.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Build adjacency dictionary
neighbors = {}
for _, row in adjacency_df.iterrows():
    boro = row['borough']
    neighbor = row['neighbor']
    if boro not in neighbors:
        neighbors[boro] = set()
    if neighbor not in neighbors:
        neighbors[neighbor] = set()
    neighbors[boro].add(neighbor)
    neighbors[neighbor].add(boro)

# Ensure all boroughs are in the neighbors dict
boroughs = no2_df['borough'].unique()
for boro in boroughs:
    if boro not in neighbors:
        neighbors[boro] = set()

# Iterative-R process
converged = False
while not converged:
    # Compute current neighbor averages
    current_neighbor_avgs = {}
    for boro in boroughs:
        if not neighbors[boro]:
            avg = np.nan
        else:
            neighbor_values = [no2_df.loc[no2_df['borough'] == n, 'NO2_value'].values[0] for n in neighbors[boro]]
            avg = np.mean(neighbor_values)
        current_neighbor_avgs[boro] = avg

    # Compute differences
    differences = {}
    for boro in boroughs:
        no2 = no2_df.loc[no2_df['borough'] == boro, 'NO2_value'].values[0]
        avg = current_neighbor_avgs[boro]
        if np.isnan(avg):
            diff = np.nan
        else:
            diff = no2 - avg
        differences[boro] = diff

    # Find max absolute difference
    max_diff = -np.inf
    max_boro = None
    for boro, diff in differences.items():
        if not np.isnan(diff) and abs(diff) > max_diff:
            max_diff = abs(diff)
            max_boro = boro

    # Check convergence
    if max_diff < 1e-6:
        converged = True
        break

    # Modify neighbor lists
    current_neighbors = list(neighbors[max_boro].copy())
    for neighbor in current_neighbors:
        if max_boro in neighbors[neighbor]:
            neighbors[neighbor].remove(max_boro)
    neighbors[max_boro].clear()

# Compute adjusted neighbor averages
adjusted_neighbor_avgs = {}
for boro in boroughs:
    if not neighbors[boro]:
        avg = np.nan
    else:
        neighbor_values = [no2_df.loc[no2_df['borough'] == n, 'NO2_value'].values[0] for n in neighbors[boro]]
        avg = np.mean(neighbor_values)
    adjusted_neighbor_avgs[boro] = avg

# Compute adjusted differences
adjusted_differences = {}
for boro in boroughs:
    no2 = no2_df.loc[no2_df['borough'] == boro, 'NO2_value'].values[0]
    avg = adjusted_neighbor_avgs[boro]
    if np.isnan(avg):
        diff = np.nan
    else:
        diff = no2 - avg
    adjusted_differences[boro] = diff

# Calculate z-score for City of London
city_of_london = 'City of London'
city_diff = adjusted_differences[city_of_london]

all_diffs = np.array([diff for diff in adjusted_differences.values() if not np.isnan(diff)])
mean_diff = np.mean(all_diffs)
std_diff = np.std(all_diffs, ddof=1)
z_score = (city_diff - mean_diff) / std_diff

data_points_used = len(all_diffs)
print(f"data_points_used = {data_points_used}")

if z_score > 1.96:
    verdict = "OUTLIER - HIGH"
elif z_score < -1.96:
    verdict = "OUTLIER - LOW"
else:
    verdict = "NOT AN OUTLIER"

print(f"FINAL ANSWER: {verdict} (z = {z_score:.2f})")

import pandas as pd
import numpy as np

# Load data
no2_df = pd.read_csv('chunks_csv/outlierr/2023_no2.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Create neighbor dictionary
boroughs = no2_df['borough'].unique()
neighbor_dict = {b: [] for b in boroughs}
for _, row in adjacency_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    neighbor_dict[borough].append(neighbor)

# Initialize current_neighbor_dict
current_neighbor_dict = {b: list(neighbors) for b, neighbors in neighbor_dict.items()}

prev_max_deviation = None
while True:
    # Compute deviations
    deviations = {}
    for borough in boroughs:
        neighbors = current_neighbor_dict[borough]
        if not neighbors:
            avg = np.nan
        else:
            no2_values = no2_df[no2_df['borough'].isin(neighbors)]['NO2_value'].values
            if len(no2_values) == 0:
                avg = np.nan
            else:
                avg = np.mean(no2_values)
        actual_value = no2_df[no2_df['borough'] == borough]['NO2_value'].values[0]
        deviations[borough] = actual_value - avg

    # Find max deviation
    valid_deviations = {b: d for b, d in deviations.items() if not pd.isna(d)}
    if not valid_deviations:
        break
    max_borough = max(valid_deviations, key=lambda k: abs(valid_deviations[k]))
    max_deviation = valid_deviations[max_borough]

    # Check for convergence
    if prev_max_deviation is not None and abs(max_deviation) == abs(prev_max_deviation):
        break
    prev_max_deviation = max_deviation

    # Remove max_borough from its neighbors' current_neighbor_dict
    for neighbor in current_neighbor_dict.get(max_borough, []):
        if max_borough in current_neighbor_dict[neighbor]:
            current_neighbor_dict[neighbor].remove(max_borough)

# Compute final averages and differences
final_averages = {}
for borough in boroughs:
    neighbors = current_neighbor_dict[borough]
    if not neighbors:
        avg = np.nan
    else:
        no2_values = no2_df[no2_df['borough'].isin(neighbors)]['NO2_value'].values
        if len(no2_values) == 0:
            avg = np.nan
        else:
            avg = np.mean(no2_values)
    final_averages[borough] = avg

differences = {}
for borough in boroughs:
    actual = no2_df[no2_df['borough'] == borough]['NO2_value'].values[0]
    avg = final_averages[borough]
    differences[borough] = actual - avg

valid_differences = [d for d in differences.values() if not pd.isna(d)]
mean_diff = np.mean(valid_differences)
std_diff = np.std(valid_differences, ddof=1)

# Handle division by zero
if std_diff == 0:
    z_score = 0.0
else:
    city_of_london_diff = differences.get('City of London', np.nan)
    if pd.isna(city_of_london_diff):
        z_score = np.nan
    else:
        z_score = (city_of_london_diff - mean_diff) / std_diff

data_points_used = len(valid_differences)
print(f"data_points_used = {data_points_used}")

if pd.isna(z_score):
    print("FINAL ANSWER: NOT AN OUTLIER (z = nan)")
else:
    if z_score > 1.96:
        print(f"FINAL ANSWER: OUTLIER - HIGH (z = {z_score:.2f})")
    elif z_score < -1.96:
        print(f"FINAL ANSWER: OUTLIER - LOW (z = {z_score:.2f})")
    else:
        print(f"FINAL ANSWER: NOT AN OUTLIER (z = {z_score:.2f})")
